```cpp
#include <Eigen/Dense>
#include <iostream>
#include <cmath>
#include <iomanip>

using namespace Eigen;

int main() {
    // Test case
    double E = 200e9, nu = 0.3, t = 0.01;
    // Nodes: (0,0), (2,0), (2,1.5), (0,1.5)
    MatrixXd coords(4,2);
    coords << 0,0,  2,0,  2,1.5,  0,1.5;

    // Constitutive matrix (plane stress)
    Matrix3d D;
    double c = E/(1.0 - nu*nu);
    D << c,      c*nu,   0,
         c*nu,   c,      0,
         0,      0,      c*(1.0-nu)/2.0;

    // Mapping: 4 triangles, each with 3 node indices (0-based)
    int M[12] = {0,1,3,  1,2,0,  2,3,1,  3,0,2};

    // KSUM: 4 blocks of 3x3 (one per quad node)
    MatrixXd KSUM[4];
    for (int i=0;i<4;i++) KSUM[i] = MatrixXd::Zero(3,3);

    for (int j=0;j<4;j++) {
        // triangle nodes
        int n0 = M[3*j+0], n1 = M[3*j+1], n2 = M[3*j+2];
        Vector2d p0 = coords.row(n0), p1 = coords.row(n1), p2 = coords.row(n2);

        // CST stiffness in global coords (2D)
        // B matrix 3x6
        double x1=p0(0),y1=p0(1),x2=p1(0),y2=p1(1),x3=p2(0),y3=p2(1);
        double A2 = (x2-x1)*(y3-y1) - (x3-x1)*(y2-y1); // 2*Area
        double A = 0.5*std::abs(A2);
        // b_i, c_i
        double b1 = y2-y3, b2 = y3-y1, b3 = y1-y2;
        double c1 = x3-x2, c2 = x1-x3, c3 = x2-x1;
        MatrixXd B(3,6);
        B << b1,0,b2,0,b3,0,
             0,c1,0,c2,0,c3,
             c1,b1,c2,b2,c3,b3;
        B /= A2; // divide by 2A
        MatrixXd K = t * A * B.transpose() * D * B; // 6x6

        // Extract 3x3 blocks: block I = rows/cols [2I,2I+1]
        for (int I=0;I<3;I++) {
            Matrix3d blk;
            for (int r=0;r<3;r++)
                for (int cc=0;cc<3;cc++)
                    blk(r,cc) = K(2*I+r, 2*I+cc);
            // add to KSUM block for node M[3j+I]
            KSUM[M[3*j+I]] += blk;
        }
    }

    // Assemble 8x8
    MatrixXd K8 = MatrixXd::Zero(8,8);
    for (int n=0;n<4;n++) {
        for (int r=0;r<3;r++)
            for (int cc=0;cc<3;cc++)
                K8(2*n+r, 2*n+cc) += KSUM[n](r,cc);
    }

    // Print JSON
    std::cout << "{\"stiffness_matrix\":[";
    for (int i=0;i<8;i++) {
        std::cout << "[";
        for (int j=0;j<8;j++) {
            std::cout << std::scientific << std::setprecision(6) << K8(i,j);
            if (j<7) std::cout << ",";
        }
        std::cout << "]";
        if (i<7) std::cout << ",";
    }
    std::cout << "]}" << std::endl;
    return 0;
}
```

